/** The tracked tables behind any relation, view or table alike. */
export function tablesBehind(relation: string): string[] {
  const r = relation.toLowerCase();
  if (VIEW_TABLES[r]) return VIEW_TABLES[r];
  return FILLED_BY[r] ? [r] : [];
}

/** Every job that fills this relation, or [] if nothing in the repo does. */
export function fillersFor(relation: string): Filler[] {
  const direct = FILLED_BY[relation.toLowerCase()];
  if (direct) return direct;
  const out: Filler[] = [];
  for (const t of tablesBehind(relation)) {
    for (const f of FILLED_BY[t] ?? []) {
      if (!out.some((e) => e.file === f.file && e.kind === f.kind)) out.push(f);
    }
  }
  return out;
}

/** One sentence naming who fills it and how often, or null if nothing does. */
export function whoFills(relation: string): string | null {
  const f = fillersFor(relation);
  if (!f.length) return null;
  const where = f[0].kind === "action" ? "the GitHub Action" : "the n8n workflow";
  const rest = f.length > 1 ? ` (and ${f.length - 1} more)` : "";
  return `Filled by ${where} \u201c${f[0].name}\u201d, ${f[0].cadence}${rest}.`;
}
